// Push the rect (rx, ry, rw, rh) with img drawn at (ix, iy) and bg everywhere
// else, one row per window write. Covering the union of the previous and the
// new position clears and redraws a moving logo in a single pass.
static inline void blitLogoImage(ILI9341_GFX* d, const LogoImage& img, int ix, int iy,
                                 int rx, int ry, int rw, int rh, uint16_t bg) {
  uint16_t row[320];
  if (rx < 0) {
    rw += rx;
    rx = 0;
  }
  if (rx + rw > 320) rw = 320 - rx;
  if (rw <= 0) return;
  for (int y = ry; y < ry + rh; ++y) {
    if (y < 0 || y >= 240) continue;
    int ly = y - iy;
    bool inRow = ly >= 0 && ly < (int)img.h;
    const uint8_t* src = img.data + ly * img.stride;
    for (int x = 0; x < rw; ++x) {
      int lx = rx + x - ix;
      uint16_t c = bg;
      if (inRow && lx >= 0 && lx < (int)img.w) {
        uint8_t i = (lx & 1) ? (src[lx >> 1] & 0x0F) : (src[lx >> 1] >> 4);
        if (i) c = OPENPOD_LOGO_PALETTE[i];
      }
      row[x] = c;
    }
    d->pushWindow(rx, y, rw, 1, row);
  }
}

// Draw wordmark glyph i (its whole column band, background included).
static inline void drawWordmarkGlyph(ILI9341_GFX* d, int i) {
  const uint16_t* ramp =
      i < OPENPOD_WORD_ACCENT_FROM ? OPENPOD_WORD_RAMP_TEXT : OPENPOD_WORD_RAMP_ACCENT;
  int x0 = OPENPOD_WORD_SPLIT[i], x1 = OPENPOD_WORD_SPLIT[i + 1];
  uint16_t row[OPENPOD_WORD_W];
  for (int y = 0; y < OPENPOD_WORD_H; ++y) {
    const uint8_t* src = OPENPOD_WORD_DATA + y * OPENPOD_WORD_STRIDE;
    for (int x = x0; x < x1; ++x) {
      uint8_t v = (x & 1) ? (src[x >> 1] & 0x0F) : (src[x >> 1] >> 4);
      row[x - x0] = ramp[v];
    }
    d->pushWindow(OPENPOD_WORD_X + x0, OPENPOD_WORD_Y + y, x1 - x0, 1, row);
  }
}
